head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > reinitialize]<br/>현재 페이지를 다시 로딩하거나 웹브라우저를 새로고침합니다.",
    "validation" : [
        "refresh(선택) 파라미터로 웹브라우저 새로고침 여부를 true/false 로 설정할 수 있어야 합니다.",
        "refresh(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "true 설정 시 브라우저를 새로고침합니다.",
        "false 설정 시 브라우저를 새로고침하지 않고 SPA 방식으로 현재 페이지만 다시 로딩합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // window 변수로 브라우저 새로고침 여부 판별
    // window 변수는 브라우저 새로고침 시 사라지고, SPA 재로딩 시 유지됨
    if (!window._reinitLoaded) {
        // 브라우저 새로고침 또는 최초 진입 → 누적 횟수 초기화
        sessionStorage.setItem("wframeload_count", "0");
        window._reinitLoaded = true;
    }

    // sessionStorage로 reinitialize 호출 여부 및 설정값 추적
    let refreshParam = sessionStorage.getItem("reinitialize_refresh");
    if (refreshParam !== null) {
        let wframeloadCount = sessionStorage.getItem("wframeload_count") || "0";

        wf_body_bottom.getObj("scwin").setReturnValue("wframeload 누적 횟수 : " + wframeloadCount);

        sessionStorage.removeItem("reinitialize_refresh");
    }
};



scwin.btn_reinitialize_onclick = function () {
    let refreshVal = par_refresh.getValue();

    // 선택한 refresh 파라미터 값 저장
    sessionStorage.setItem("reinitialize_refresh", refreshVal);

    if (refreshVal === '') {
        // refresh 파라미터 생략 (기본값 false)
        WebSquare.util.reinitialize();
    } else if (refreshVal === 'true') {
        WebSquare.util.reinitialize(true);
    } else {
        WebSquare.util.reinitialize(false);
    }
}



scwin.wf_body_sample_onwframeload = function () {
    // wframeload 이벤트 횟수 누적 (SPA 재로딩 시 누적, 브라우저 새로고침 시 onpageload에서 초기화)
    let count = Number(sessionStorage.getItem("wframeload_count") || "0") + 1;
    sessionStorage.setItem("wframeload_count", String(count));
};
